import java.util.*;
import java.io.*;
public class Text_Document_Analysis
{
    public static void main(String args[]) throws Exception
    {
        BufferedReader reader=new BufferedReader(new InputStreamReader(System.in));
        // BufferedReader reader=new BufferedReader(new FileReader("Text_Document_Analysis.in"));
        reader.readLine();
        String line=reader.readLine();
        String[] parts=line.split("\\([a-zA-Z_]*\\)");
        int maxLength=0;
        for(String part: parts)
        {
            String[] segments=part.split("_+");
            for(String segment: segments)
                maxLength=Math.max(maxLength, segment.length());
        }
        int count=0;
        int parenthesesCount=0;
        boolean insideParentheses=false;
        boolean counted=false;
        for(int i=0; i<line.length(); i++)
        {
            char c=line.charAt(i);
            if(c=='(')
                insideParentheses=true;
            if(c==')')
            {
                counted=false;
                insideParentheses=false;
            }
            if(insideParentheses && Character.isLetter(c))
            {
                if(counted) continue;
                parenthesesCount++;
                counted=true;
            }
            if(c=='_')
                counted=false;
        }
        System.out.println(maxLength+" "+parenthesesCount);
    }
}
